/** static u8 GetLinkPlayerIdAt(s16 x, s16 y) */
export function GetLinkPlayerIdAt(x: any, y: any): any {
  let i: any = null;
      for (i = 0; i < MAX_LINK_PLAYERS; i++)
      {
          if (gLinkPlayerObjectEvents[i].active
           && (gLinkPlayerObjectEvents[i].movementMode == 0 || gLinkPlayerObjectEvents[i].movementMode == 2))
          {
              let objEvent: any =gObjectEvents[gLinkPlayerObjectEvents[i].objEventId];
              if (objEvent.currentCoords.x == x && objEvent.currentCoords.y == y)
                  return i;
          }
      }
      return 4;
}

/** static void SetPlayerFacingDirection(u8 linkPlayerId, u8 facing) */
export function SetPlayerFacingDirection(linkPlayerId: any, facing: any): any {
  let linkPlayerObjEvent: any =gLinkPlayerObjectEvents[linkPlayerId];
      let objEventId: any = linkPlayerObjEvent.objEventId;
      let objEvent: any =gObjectEvents[objEventId];

      if (linkPlayerObjEvent.active)
      {
          if (facing > FACING_FORCED_RIGHT)
          {
              objEvent.triggerGroundEffectsOnMove = TRUE;
          }
          else
          {

              sMovementStatusHandler[TEMP](linkPlayerObjEvent, objEvent);
          }
      }
}

